const MethodDeclaration* SemanticAnalyzer::findMethod(const ClassDeclaration& declaration,
                                                      const std::string& name) const {
    for (const auto& method : declaration.methods) {
        if (method.name == name && !method.constructor) return &method;
    }
    if (accessibleMemberCount(declaration, name, true) != 1) return nullptr;
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base != classes_.end() &&
            basePathAccessible(declaration, {baseName}) &&
            accessibleMemberCount(*base->second, name, true) != 0) {
            return findMethod(*base->second, name);
        }
    }
    return nullptr;
}

std::vector<const MethodDeclaration*> SemanticAnalyzer::findOverloads(
    const ClassDeclaration& declaration, const std::string& name) const {
    std::vector<const MethodDeclaration*> found;
    const auto add = [&found](const MethodDeclaration* candidate) {
        for (const auto* existing : found) {
            if (sameParameterTypes(*existing, *candidate)) return;
        }
        found.push_back(candidate);
    };
    const auto visit = [this, &name, &add](const auto& self,
                                           const ClassDeclaration& current) -> void {
        for (const auto& method : current.methods) {
            if (method.name == name && !method.constructor && !method.destructor) add(&method);
        }
        for (const auto& baseName : current.baseClassNames) {
            const auto base = classes_.find(baseName);
            if (base != classes_.end()) self(self, *base->second);
        }
    };
    visit(visit, declaration);
    return found;
}

int SemanticAnalyzer::conversionRank(const std::string& target,
                                    const std::string& source,
                                    const Expression& argument) const {
    if (target == source) return 0;
    if (source == "int" && target == "unsigned" &&
        argument.kind == ExpressionKind::Integer) {
        return 1;
    }
    if (source == "null" && classes_.find(target) != classes_.end()) return 2;
    if (!isAssignable(target, source)) return -1;

    if (classes_.find(source) != classes_.end() &&
        classes_.find(target) != classes_.end()) {
        std::vector<std::pair<std::string, int>> pending{{source, 0}};
        std::unordered_set<std::string> visited;
        while (!pending.empty()) {
            const auto current = pending.back();
            pending.pop_back();
            if (!visited.emplace(current.first).second) continue;
            if (current.first == target) return 2 + current.second;
            const auto declaration = classes_.find(current.first);
            if (declaration == classes_.end()) continue;
            for (const auto& baseName : declaration->second->baseClassNames) {
                pending.emplace_back(baseName, current.second + 1);
            }
        }
    }
    return 20;
}

const MethodDeclaration* SemanticAnalyzer::selectOverload(
    const std::vector<const MethodDeclaration*>& candidates,
    const std::vector<std::unique_ptr<Expression>>& arguments,
    const std::vector<std::string>& argumentTypes, bool& ambiguous) {
    ambiguous = false;
    std::vector<std::pair<const MethodDeclaration*, std::vector<int>>> viable;
    for (const auto* candidate : candidates) {
        if (candidate->parameters.size() != argumentTypes.size()) continue;
        std::vector<int> ranks;
        bool matches = true;
        for (std::size_t index = 0; index < argumentTypes.size(); ++index) {
            auto source = argumentTypes[index];
            if (source == "<contextual-callback>") {
                auto probe = cloneExpression(*arguments[index]);
                try {
                    source = analyzeExpression(*probe, candidate->parameters[index].type);
                } catch (const DiagnosticError&) {
                    // This overload's context cannot resolve the capture.
                    matches = false;
                    break;
                }
            }
            const auto rank = conversionRank(candidate->parameters[index].type,
                                             source, *arguments[index]);
            if (rank < 0) {
                matches = false;
                break;
            }

            ranks.push_back(rank);
        }
        if (matches) viable.emplace_back(candidate, std::move(ranks));
    }
    if (viable.empty()) return nullptr;

    std::vector<const MethodDeclaration*> best;
    for (const auto& candidate : viable) {
        bool dominated = false;
        for (const auto& other : viable) {
            if (candidate.first == other.first) continue;
            bool noWorse = true;
            bool strictlyBetter = false;
            for (std::size_t index = 0; index < candidate.second.size(); ++index) {
                noWorse = noWorse && other.second[index] <= candidate.second[index];
                strictlyBetter = strictlyBetter ||
                                 other.second[index] < candidate.second[index];
            }
            if (noWorse && strictlyBetter) {
                dominated = true;
                break;
            }
        }
        if (!dominated) best.push_back(candidate.first);
    }
    ambiguous = best.size() != 1;
    return ambiguous ? nullptr : best.front();
}

std::string SemanticAnalyzer::overloadArgumentType(
    Expression& argument, const std::vector<const MethodDeclaration*>& candidates,
    std::size_t index) {
    if (argument.kind == ExpressionKind::Member) {
        for (const auto* candidate : candidates) {
            if (index < candidate->parameters.size() &&
                isCallbackType(candidate->parameters[index].type))
                return "<contextual-callback>";
        }
    }
    return analyzeExpression(argument);
}

std::size_t SemanticAnalyzer::countMethods(const ClassDeclaration& declaration,
                                           const std::string& name) const {
    std::unordered_set<std::string> seenVirtual;
    const auto visit = [this, &name, &seenVirtual](const auto& self,
                                                   const ClassDeclaration& current)
        -> std::size_t {
        for (const auto& method : current.methods) {
            if (method.name == name && !method.constructor) return 1;
        }
        std::size_t count = 0;
        for (std::size_t index = 0; index < current.baseClassNames.size(); ++index) {
            const auto& baseName = current.baseClassNames[index];
            const auto base = classes_.find(baseName);
            if (base != classes_.end()) {
                if (current.baseVirtual[index] && !seenVirtual.emplace(baseName).second)
                    continue;
                count += self(self, *base->second);
            }
        }
        return count;
    };
    return visit(visit, declaration);
}

std::vector<std::string> SemanticAnalyzer::virtualBaseNames(
    const ClassDeclaration& declaration) const {
    std::vector<std::string> result;
    std::unordered_set<std::string> seen;
    const auto visit = [this, &result, &seen](const auto& self,
                                              const ClassDeclaration& current) -> void {
        for (std::size_t index = 0; index < current.baseClassNames.size(); ++index) {
            const auto& baseName = current.baseClassNames[index];
            const auto base = classes_.find(baseName);
            if (base == classes_.end()) continue;
            if (current.baseVirtual[index] && !seen.emplace(baseName).second) continue;
            self(self, *base->second);
            if (current.baseVirtual[index]) result.push_back(baseName);
        }
    };
    visit(visit, declaration);
    return result;
}

bool SemanticAnalyzer::isSubclassOf(const std::string& type, const std::string& base) const {
    const auto found = classes_.find(type);
    if (found == classes_.end()) return false;
    if (type == base) return true;
    std::vector<const ClassDeclaration*> pending{found->second};
    std::unordered_set<std::string> visited;
    while (!pending.empty()) {
        const auto* current = pending.back();
        pending.pop_back();
        if (!visited.emplace(current->name).second) continue;
        for (const auto& baseName : current->baseClassNames) {
            if (baseName == base) return true;
            const auto parent = classes_.find(baseName);
            if (parent != classes_.end()) pending.push_back(parent->second);
        }
    }
    return false;
}

bool SemanticAnalyzer::isAssignable(const std::string& target,
                                    const std::string& source) const {
    if (target == source) return true;
    if (isCallbackType(target) || isCallbackType(source))
        return isCallbackType(target) && source == "null";
    // 'any' is the dynamic/tagged value representation returned by collection
    // reads; it may hold primitive values and managed references.
    if (target == "any") {
        return source == "int" || source == "bool" || source == "float" ||
               source == "unsigned" || source == "String" || source == "null" ||
               source == "list" || source == "dict" || source == "buffer" ||
               source == "handle" || source == "type" ||
               classes_.find(source) != classes_.end();
    }
    if (source == "any") {
        return target == "int" || target == "bool" || target == "float" ||
               target == "unsigned" || target == "String" || target == "dict" ||
               target == "list" || target == "buffer" || target == "handle" ||
               classes_.find(target) != classes_.end();
    }
    if (source == "null") {
        // Universal-null model (confirmed): null is assignable to every type,
        // including scalars. Scalar null-holding is supported for local
        // variables only (see the "Nullability model (confirmed)" note in
        // SIMPLE-LANGUAGE-NOTES.md); other scalar contexts (fields, list/dict
        // elements, function arguments/returns) are unaffected by this and
        // continue to use the plain unboxed representation.
        return target == "buffer" || target == "handle" || target == "String" ||
               target == "list" || target == "dict" || target == "int" ||
               target == "unsigned" || target == "float" || target == "bool" ||
               target == "type" || classes_.find(target) != classes_.end();
    }
    const auto found = classes_.find(source);
    if (classes_.find(target) == classes_.end() || found == classes_.end() ||
        !isSubclassOf(source, target)) return false;
    std::unordered_set<std::string> seenVirtual;
    const auto countPaths = [this, &target, &seenVirtual](
                                const auto& self, const ClassDeclaration& owner)
        -> std::size_t {
        std::size_t count = 0;
        for (std::size_t index = 0; index < owner.baseClassNames.size(); ++index) {
            const auto& baseName = owner.baseClassNames[index];
            const auto base = classes_.find(baseName);
            if (base == classes_.end()) continue;
            if (baseName == target) {
                if (!owner.baseVirtual[index] ||
                    seenVirtual.emplace(baseName).second) ++count;
            } else {
                if (owner.baseVirtual[index] && !seenVirtual.emplace(baseName).second)
                    continue;
                count += self(self, *base->second);
            }
        }
        return count;
    };
    if (countPaths(countPaths, *found->second) != 1) return false;
    const auto findPath = [this, &target](const auto& self,
                                          const ClassDeclaration& owner,
                                          std::vector<std::pair<const ClassDeclaration*,
                                                                std::size_t>>& path)
        -> bool {
        for (std::size_t index = 0; index < owner.baseClassNames.size(); ++index) {
            const auto& baseName = owner.baseClassNames[index];
            const auto base = classes_.find(baseName);
            if (base == classes_.end()) continue;
            path.emplace_back(&owner, index);
            if (baseName == target || self(self, *base->second, path)) return true;
            path.pop_back();
        }
        return false;
    };
    std::vector<std::pair<const ClassDeclaration*, std::size_t>> path;
    if (!findPath(findPath, *found->second, path)) return false;
    AccessLevel effective = AccessLevel::Public;
    std::string restrictedAt;
    for (const auto& edge : path) {
        const auto access = edge.first->baseAccess[edge.second];
        if (access == AccessLevel::Private) {
            effective = AccessLevel::Private;
            restrictedAt = edge.first->name;
        } else if (access == AccessLevel::Protected &&
                   effective == AccessLevel::Public) {
            effective = AccessLevel::Protected;
            restrictedAt = edge.first->name;
        }
    }
    if (effective == AccessLevel::Public) return true;
    if (currentClass_ == nullptr) return false;
    if (effective == AccessLevel::Private) return currentClass_->name == restrictedAt;
    return currentClass_->name == restrictedAt ||
           isSubclassOf(currentClass_->name, restrictedAt);
}

std::vector<const FieldDeclaration*> SemanticAnalyzer::inheritedFields(
    const ClassDeclaration& declaration) const {
    std::vector<const FieldDeclaration*> fields;
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base != classes_.end()) {
            auto inherited = inheritedFields(*base->second);
            fields.insert(fields.end(), inherited.begin(), inherited.end());
        }
    }
    for (const auto& field : declaration.fields) fields.push_back(&field);
    return fields;
}

